quiz.answer:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.split("\n").filter((line) => line.trim() !== "");

let count = 0;
let total = 0;
for (const line of lines) {
  count = count + 1;
  total = total + Number(line);
}
console.log(`件数: ${count} / 合計: ${total}円`);

